{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    allocations = [s['minimum'] for s in segments]
    remaining = budget - sum(allocations)
    while remaining > 0:
        best_idx = -1
        best_imp = -1
        for i, s in enumerate(segments):
            if allocations[i] < s['capacity'] and s['importance'] > best_imp:
                best_imp = s['importance']
                best_idx = i
        if best_idx == -1:
            break
        allocations[best_idx] += 1
        remaining -= 1
    by_name = {s['name']: allocations[i] for i, s in enumerate(segments)}
    return {'allocations': allocations, 'by_name': by_name, 'total': budget}"}
